import subprocess, re, os
base='/home/runner/work/beetle-in-the-anthill/beetle-in-the-anthill'
recorded=set()
for root,_,files in os.walk('/tmp/main-wt'):
    for f in files:
        if f.endswith('.md'):
            for line in open(os.path.join(root,f)):
                m=re.search(r'Source: friend/\w+ @ ([0-9a-f]{40})',line)
                if m: recorded.add(m.group(1))
out=subprocess.check_output(['git','-C',base,'rev-list','--reverse','origin/friend/phoebe'], text=True).split()
for sha in out:
    msg=subprocess.check_output(['git','-C',base,'log','-1','--format=%B',sha], text=True)
    if 'Friend-Message: 1' not in msg: continue
    if sha in recorded: continue
    print(repr(sha))
    print('---MSG---')
    print(msg)
    break
